CREATE TABLE "c_Cart" ("id" BIGINT NOT NULL, "a_Cart_status" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Order" ("id" BIGINT NOT NULL, "a_Order_total" NUMERIC NOT NULL, "a_Order_ordered_at" TIMESTAMP NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Product" ("id" BIGINT NOT NULL, "a_Product_sku" TEXT NOT NULL, "a_Product_price" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Review" ("id" BIGINT NOT NULL, "a_Review_rating" BIGINT NOT NULL, "a_Review_body" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_User" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Admin_role_level" BIGINT, "a_Customer_loyalty_points" BIGINT, "a_User_email" TEXT, "a_User_created_at" TIMESTAMP, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Admin','Customer','User')), CHECK ((dtype IN ('Admin')) OR "a_Admin_role_level" IS NULL), CHECK (NOT (dtype IN ('Admin')) OR "a_Admin_role_level" IS NOT NULL), CHECK ((dtype IN ('Customer')) OR "a_Customer_loyalty_points" IS NULL), CHECK (NOT (dtype IN ('Customer')) OR "a_Customer_loyalty_points" IS NOT NULL), CHECK ((dtype IN ('Admin','Customer','User')) OR "a_User_email" IS NULL), CHECK (NOT (dtype IN ('Admin','Customer','User')) OR "a_User_email" IS NOT NULL), CHECK ((dtype IN ('Admin','Customer','User')) OR "a_User_created_at" IS NULL), CHECK (NOT (dtype IN ('Admin','Customer','User')) OR "a_User_created_at" IS NOT NULL));
CREATE TABLE "l_CustomerCart" ("r_CustomerCart_source_id" BIGINT NOT NULL, "r_CustomerCart_source_dtype" TEXT NOT NULL, "r_CustomerCart_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_CustomerCart_source_id", "r_CustomerCart_target_id"), UNIQUE ("r_CustomerCart_target_id"), UNIQUE ("r_CustomerCart_source_id"), CHECK ("r_CustomerCart_source_dtype" IS NULL OR "r_CustomerCart_source_dtype" IN ('Customer')));
CREATE TABLE "l_CustomerOrders" ("r_CustomerOrders_source_id" BIGINT NOT NULL, "r_CustomerOrders_source_dtype" TEXT NOT NULL, "r_CustomerOrders_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_CustomerOrders_source_id", "r_CustomerOrders_target_id"), UNIQUE ("r_CustomerOrders_target_id"), CHECK ("r_CustomerOrders_source_dtype" IS NULL OR "r_CustomerOrders_source_dtype" IN ('Customer')));
CREATE TABLE "l_OrderProducts" ("r_OrderProducts_source_id" BIGINT NOT NULL, "r_OrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_OrderProducts_source_id", "r_OrderProducts_target_id"));
CREATE TABLE "l_ProductReviews" ("r_ProductReviews_source_id" BIGINT NOT NULL, "r_ProductReviews_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_ProductReviews_source_id", "r_ProductReviews_target_id"), UNIQUE ("r_ProductReviews_target_id"));
ALTER TABLE "l_CustomerCart" ADD CONSTRAINT "fk_l_CustomerCart_0" FOREIGN KEY ("r_CustomerCart_source_id", "r_CustomerCart_source_dtype") REFERENCES "c_User" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CustomerCart" ADD CONSTRAINT "fk_l_CustomerCart_1" FOREIGN KEY ("r_CustomerCart_target_id") REFERENCES "c_Cart" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CustomerOrders" ADD CONSTRAINT "fk_l_CustomerOrders_0" FOREIGN KEY ("r_CustomerOrders_source_id", "r_CustomerOrders_source_dtype") REFERENCES "c_User" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CustomerOrders" ADD CONSTRAINT "fk_l_CustomerOrders_1" FOREIGN KEY ("r_CustomerOrders_target_id") REFERENCES "c_Order" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrderProducts" ADD CONSTRAINT "fk_l_OrderProducts_0" FOREIGN KEY ("r_OrderProducts_source_id") REFERENCES "c_Order" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrderProducts" ADD CONSTRAINT "fk_l_OrderProducts_1" FOREIGN KEY ("r_OrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProductReviews" ADD CONSTRAINT "fk_l_ProductReviews_0" FOREIGN KEY ("r_ProductReviews_source_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProductReviews" ADD CONSTRAINT "fk_l_ProductReviews_1" FOREIGN KEY ("r_ProductReviews_target_id") REFERENCES "c_Review" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_CustomerCart"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Cart" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_CustomerCart" l WHERE l."r_CustomerCart_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: CustomerCart'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_CustomerCart_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Cart" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerCart"();
CREATE CONSTRAINT TRIGGER "ct_CustomerCart_link" AFTER INSERT OR UPDATE OR DELETE ON "l_CustomerCart" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerCart"();
CREATE FUNCTION "require_CustomerOrders"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Order" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_CustomerOrders" l WHERE l."r_CustomerOrders_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: CustomerOrders'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_CustomerOrders_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Order" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerOrders"();
CREATE CONSTRAINT TRIGGER "ct_CustomerOrders_link" AFTER INSERT OR UPDATE OR DELETE ON "l_CustomerOrders" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CustomerOrders"();
CREATE FUNCTION "require_ProductReviews"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Review" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_ProductReviews" l WHERE l."r_ProductReviews_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: ProductReviews'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_ProductReviews_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Review" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ProductReviews"();
CREATE CONSTRAINT TRIGGER "ct_ProductReviews_link" AFTER INSERT OR UPDATE OR DELETE ON "l_ProductReviews" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_ProductReviews"();